import os
from flask import Flask, abort, request, send_file

app = Flask(__name__)
BASE = os.path.realpath("/srv/files")

@app.route("/download")
def download():
    name = request.args.get("name")
    if not name:
        abort(400)
    path = os.path.join(BASE, name)
    if not os.path.realpath(path).startswith(BASE):
        abort(400)
    return send_file(path)

